window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EPH"]={"book":"EPH","editions":{"dan-1819":[[1,1,"Paulus, Jesu Christi Apostel ved Guds Villie, til de Hellige, som ere i Ephesus, de Troende i Christus Jesus:","Paulus, Jesu Christi Apostel ved Guds Villie, til de Hellige, som ere i Ephesus, de Troende i Christus Jesus:"],[1,2,"Naade være med Eder og Fred, fra Gud vor Fader og den Herre Jesus Christus!","Naade være med Eder og Fred, fra Gud vor Fader og den Herre Jesus Christus!"],[1,3,"Lovet være Gud og vor Herres Jesu Christi Fader, som velsignede os med al aandelig Velsignelse i det Himmelske, i Christus!","Lovet være Gud og vor Herres Jesu Christi Fader, som velsignede os med al aandelig Velsignelse i det Himmelske, i Christus!"],[1,4,"ligesom han udvalgte os i ham, før Verdens Grundvold blev lagt, at vi skulle være hellige og ustraffelige for hans Aasyn i Kjærlighed;","ligesom han udvalgte os i ham, før Verdens Grundvold blev lagt, at vi skulle være hellige og ustraffelige for hans Aasyn i Kjærlighed;"],[1,5,"idet han forud bestemte os formedelst Jesus Christus til sønlig Udkaarelse hos sig selv, efter sin Villies Velbehagelighed,","idet han forud bestemte os formedelst Jesus Christus til sønlig Udkaarelse hos sig selv, efter sin Villies Velbehagelighed,"],[1,6,"sin herlige Naade til Lov, ved hvilken han benaadede os i den Elskte,","sin herlige Naade til Lov, ved hvilken han benaadede os i den Elskte,"],[1,7,"i hvem vi have Forløsning formedelst hans Blod, Syndernes Forladelse, efter hans Naades Rigdom,","i hvem vi have Forløsning formedelst hans Blod, Syndernes Forladelse, efter hans Naades Rigdom,"],[1,8,"hvilken han overflødigen tildeelte os i al Viisdom og Forstand,","hvilken han overflødigen tildeelte os i al Viisdom og Forstand,"],[1,9,"idet han kundgjorde os sin Villies Hemmelighed, efter den velbehagelige Beslutning, hvilken han forud satte hos sig selv,","idet han kundgjorde os sin Villies Hemmelighed, efter den velbehagelige Beslutning, hvilken han forud satte hos sig selv,"],[1,10,"at oprette en Huusholdning i Tidernes Fylde, for at samle Alt under eet Hoved udi Christus, baade det, som er i Himlene og paa Jorden, udi ham;","at oprette en Huusholdning i Tidernes Fylde, for at samle Alt under eet Hoved udi Christus, baade det, som er i Himlene og paa Jorden, udi ham;"],[1,11,"i hvem ogsaa vi have faaet Lod, vi, som forud vare bestemte efter hans Beslutning, som virker Alt efter sin Villies Raad,","i hvem ogsaa vi have faaet Lod, vi, som forud vare bestemte efter hans Beslutning, som virker Alt efter sin Villies Raad,"],[1,12,"paa det vi maatte være hans Herlighed til Lov, vi, som forud haabede paa Christus.","paa det vi maatte være hans Herlighed til Lov, vi, som forud haabede paa Christus."],[1,13,"Udi ham ere ogsaa I, da i hørte Sandhedens Ord, Eders Saliggjørelses Evangelium, udi ham ere ogsaa I, der I troede, blevne beseglede med Forjættelsens hellige Aand,","Udi ham ere ogsaa I, da i hørte Sandhedens Ord, Eders Saliggjørelses Evangelium, udi ham ere ogsaa I, der I troede, blevne beseglede med Forjættelsens hellige Aand,"],[1,14,"som er os Pant paa vor Arv til Eiendommens Forløsning, hans Herlighed til Lov.","som er os Pant paa vor Arv til Eiendommens Forløsning, hans Herlighed til Lov."],[1,15,"Hvorfor ogsaa jeg, efter at have hørt om Eders Tro paa den Herre Jesus og om Eders Kjærlighed til alle de Hellige,","Hvorfor ogsaa jeg, efter at have hørt om Eders Tro paa den Herre Jesus og om Eders Kjærlighed til alle de Hellige,"],[1,16,"ikke aflader at takke for Eder, idet jeg ihukommer Eder i alle mine Bønner,","ikke aflader at takke for Eder, idet jeg ihukommer Eder i alle mine Bønner,"],[1,17,"at vor Herres Jesu Christi Gud, Herlighedens Fader, vilde give Eder Viisdoms og Aabenbarelses Aand udi hans Kundskab,","at vor Herres Jesu Christi Gud, Herlighedens Fader, vilde give Eder Viisdoms og Aabenbarelses Aand udi hans Kundskab,"],[1,18,"Eders Forstands oplyste Øine, at I kunne kjende, hvilket det Haab er, som han kaldte Eder til, og hvilken hans Arvs herlige Rigdom er iblandt de Hellige,","Eders Forstands oplyste Øine, at I kunne kjende, hvilket det Haab er, som han kaldte Eder til, og hvilken hans Arvs herlige Rigdom er iblandt de Hellige,"],[1,19,"og hvilken hans Magts overvættes Storhed er over os, som troe efter hans vældige Krafts Virkning,","og hvilken hans Magts overvættes Storhed er over os, som troe efter hans vældige Krafts Virkning,"],[1,20,"som han udviste i Christus, der han opreiste ham fra de Døde, og satte ham hos sin høire Haand i Himlene,","som han udviste i Christus, der han opreiste ham fra de Døde, og satte ham hos sin høire Haand i Himlene,"],[1,21,"langt over al Fyrstendom og Myndighed og Magt og Herredom og alt Navn, som nævnes, ikke alene i denne Verden, men ogsaa i den tilkommende;","langt over al Fyrstendom og Myndighed og Magt og Herredom og alt Navn, som nævnes, ikke alene i denne Verden, men ogsaa i den tilkommende;"],[1,22,"og lagde Alt under hans Fødder, og satte ham til Hoved over Alting for Menigheden,","og lagde Alt under hans Fødder, og satte ham til Hoved over Alting for Menigheden,"],[1,23,"der er hans Legeme, hvilket ham fylder, som opfylder Alt i Alle.","der er hans Legeme, hvilket ham fylder, som opfylder Alt i Alle."],[2,1,"Ogsaa Eder gjorde han levende, der I vare døde i Overtrædelser og Synder,","Ogsaa Eder gjorde han levende, der I vare døde i Overtrædelser og Synder,"],[2,2,"udi hvilke I forhen vandrede efter denne Verdens Skik, efter den Fyrstes Viis, som haver Magt i Luften, den Aands, der nu er virksom i Vantroens Børn,","udi hvilke I forhen vandrede efter denne Verdens Skik, efter den Fyrstes Viis, som haver Magt i Luften, den Aands, der nu er virksom i Vantroens Børn,"],[2,3,"iblandt hvilke ogsaa vi alle forhen vandrede i vort Kjøds Begjerligheder, og gjorde Kjødets og Lysternes Villie, og vare af naturen Vredens Børn, som og de Andre.","iblandt hvilke ogsaa vi alle forhen vandrede i vort Kjøds Begjerligheder, og gjorde Kjødets og Lysternes Villie, og vare af naturen Vredens Børn, som og de Andre."],[2,4,"Men Gud, som er rig paa Barmhjertighed, formedelst sin store Kjærlighed, med hvilken han elskede os,","Men Gud, som er rig paa Barmhjertighed, formedelst sin store Kjærlighed, med hvilken han elskede os,"],[2,5,"Levendegjorde ogsaa os med Christus, der vi vare døde i Overtrædelserne, (af Naade ere I frelste!)","Levendegjorde ogsaa os med Christus, der vi vare døde i Overtrædelserne, (af Naade ere I frelste!)"],[2,6,"og opreiste os tillige og satte os tillige i det himmelske Rige ved Christus Jesus,","og opreiste os tillige og satte os tillige i det himmelske Rige ved Christus Jesus,"],[2,7,"paa det han i de tilkommende Tider kunde vise sin Naades overvættes Rigdom i Godhed mod os udi Christus Jesus.","paa det han i de tilkommende Tider kunde vise sin Naades overvættes Rigdom i Godhed mod os udi Christus Jesus."],[2,8,"Thi af Naade ere I frelste formedelst Troen, og det ikke af Eder, det er en Guds Gave;","Thi af Naade ere I frelste formedelst Troen, og det ikke af Eder, det er en Guds Gave;"],[2,9,"ikke af Gjerninger, at ikke Nogen skal rose sig.","ikke af Gjerninger, at ikke Nogen skal rose sig."],[2,10,"Thi vi ere hans Værk, skabte i Christus Jesus til gode Gjerninger, til hvilke Gud forud beredte os, at vi skulle vandre i dem.","Thi vi ere hans Værk, skabte i Christus Jesus til gode Gjerninger, til hvilke Gud forud beredte os, at vi skulle vandre i dem."],[2,11,"Derfor kommer ihu, at I, som forhen vare Hedninger efter Kjødet, og bleve kaldte Forhud af den saakaldte Omskærelse, den i Kjødet, som skeer med Haanden,","Derfor kommer ihu, at I, som forhen vare Hedninger efter Kjødet, og bleve kaldte Forhud af den saakaldte Omskærelse, den i Kjødet, som skeer med Haanden,"],[2,12,"at I paa den Tid vare uden Christus, udelukte fra Israels Borgerret og fremmede fra Forjættelsens Pagter, uden Haab og uden Gud i Verden.","at I paa den Tid vare uden Christus, udelukte fra Israels Borgerret og fremmede fra Forjættelsens Pagter, uden Haab og uden Gud i Verden."],[2,13,"Men i Christus Jesus ere nu I, som forhen vare langt borte, komne nær til ved Christi Blod.","Men i Christus Jesus ere nu I, som forhen vare langt borte, komne nær til ved Christi Blod."],[2,14,"Thi han er vor Fred, som gjorde eet af begge, og nedbrød Adskillelsens Mellemvæg,","Thi han er vor Fred, som gjorde eet af begge, og nedbrød Adskillelsens Mellemvæg,"],[2,15,"da han i sit Kjød afskaffede Fjendskabet, Budenes Lov med dens Befalinger, paa det han ved sig selv kunde skabe de To til eet nyt Menneske og gjøre Fred,","da han i sit Kjød afskaffede Fjendskabet, Budenes Lov med dens Befalinger, paa det han ved sig selv kunde skabe de To til eet nyt Menneske og gjøre Fred,"],[2,16,"og forlige dem begge i eet Legeme med Gud formedelst Korset, da han ved dette ihjelslog Fjendskabet.","og forlige dem begge i eet Legeme med Gud formedelst Korset, da han ved dette ihjelslog Fjendskabet."],[2,17,"Og han kom og forkyndte Fred for Eder, som vare langt borte, og for dem, som vare nær.","Og han kom og forkyndte Fred for Eder, som vare langt borte, og for dem, som vare nær."],[2,18,"Thi formedelst ham have vi begge Adgang i een Aand til Faderen.","Thi formedelst ham have vi begge Adgang i een Aand til Faderen."],[2,19,"Saa ere I da ikke mere Gjester og Fremmede, men de Helliges Medborgere og Guds Huusfolk,","Saa ere I da ikke mere Gjester og Fremmede, men de Helliges Medborgere og Guds Huusfolk,"],[2,20,"opbygte paa Apostlernes og Propheternes Grundvold, saa Jesus Christus selv er Hovedhjørnestenen,","opbygte paa Apostlernes og Propheternes Grundvold, saa Jesus Christus selv er Hovedhjørnestenen,"],[2,21,"paa hvilken den ganske Bygning sammenføiet voxer til et helligt Tempel i Herren,","paa hvilken den ganske Bygning sammenføiet voxer til et helligt Tempel i Herren,"],[2,22,"paa hvilken ogsaa I tillige blive bygte til Guds Bolig i Aanden.","paa hvilken ogsaa I tillige blive bygte til Guds Bolig i Aanden."],[3,1,"For hvilken Sags Skyld jeg Paulus, Christi Jesu Bundne for Eder, Hedninger:","For hvilken Sags Skyld jeg Paulus, Christi Jesu Bundne for Eder, Hedninger:"],[3,2,"(I have jo hørt om Guds Naades Huusholdning, som mig er given til Eder,","(I have jo hørt om Guds Naades Huusholdning, som mig er given til Eder,"],[3,3,"at han ved Aabenbarelse haver kundgjort mig hiin Hemmlighed, hvorom jeg foran haver korteligen skrevet,","at han ved Aabenbarelse haver kundgjort mig hiin Hemmlighed, hvorom jeg foran haver korteligen skrevet,"],[3,4,"af hvilket I kunne, naar i det læse, skjønne min Indsigt i Christi Hemmlighed;","af hvilket I kunne, naar i det læse, skjønne min Indsigt i Christi Hemmlighed;"],[3,5,"hvilken i de forrige Tider ikke var kundgjort for Menneskens Børn, som den nu er aabenbaret hans hellige Apostler og Propheter i Aanden:","hvilken i de forrige Tider ikke var kundgjort for Menneskens Børn, som den nu er aabenbaret hans hellige Apostler og Propheter i Aanden:"],[3,6,"at Hedningerne ere Medarvinger og medindlemmede og meddeelagtige i hans Forjættelse i Christus, formedelst Evangelium.","at Hedningerne ere Medarvinger og medindlemmede og meddeelagtige i hans Forjættelse i Christus, formedelst Evangelium."],[3,7,"hvis Tjener jeg er bleven ifølge den Guds Naades Gave, som mig er given efter hans vældige Kraft.","hvis Tjener jeg er bleven ifølge den Guds Naades Gave, som mig er given efter hans vældige Kraft."],[3,8,"Mig, den Allerringeste af alle Hellige, er denne Naade given, at prædike for Hedningerne Christi uransagelige Rigdom,","Mig, den Allerringeste af alle Hellige, er denne Naade given, at prædike for Hedningerne Christi uransagelige Rigdom,"],[3,9,"og at oplyse Alle om Deelagtigheden i den Hemmelighed, som fra Verdens Begyndelse haver været skjult i Gud, som skabte alle Ting ved Jesus Christus,","og at oplyse Alle om Deelagtigheden i den Hemmelighed, som fra Verdens Begyndelse haver været skjult i Gud, som skabte alle Ting ved Jesus Christus,"],[3,10,"saa at Guds mangfoldige Viisdom skulde nu blive kundgjort for Fyrstendømmer og Magter i Himlen ved Menigheden,","saa at Guds mangfoldige Viisdom skulde nu blive kundgjort for Fyrstendømmer og Magter i Himlen ved Menigheden,"],[3,11,"efter en evig Beslutning, hvilken han fuldbyrdede ved Christus Jesus, vor Herre,","efter en evig Beslutning, hvilken han fuldbyrdede ved Christus Jesus, vor Herre,"],[3,12,"i hvem vi have Frimodighed og Adgang med Tillid ved Troen paa ham.","i hvem vi have Frimodighed og Adgang med Tillid ved Troen paa ham."],[3,13,"Derfor beder jeg, at I ikke forsage over mine Trængsler, som jeg lider for Eder, hvilket er Eders Ære.)","Derfor beder jeg, at I ikke forsage over mine Trængsler, som jeg lider for Eder, hvilket er Eders Ære.)"],[3,14,"For denne Sags Skyld bøier jeg mine Knæ for vor Herres Jesu Christi Fader,","For denne Sags Skyld bøier jeg mine Knæ for vor Herres Jesu Christi Fader,"],[3,15,"af hvem al Faderlighed kaldes i Himlene og paa Jorden,","af hvem al Faderlighed kaldes i Himlene og paa Jorden,"],[3,16,"at han vil give Eder efter sin Herligheds Rigdom mægtigen at bekræftes ved hans Aand i det indvortes Menneske;","at han vil give Eder efter sin Herligheds Rigdom mægtigen at bekræftes ved hans Aand i det indvortes Menneske;"],[3,17,"at Christus maa boe formedelst Troen i Eders Hjerter,","at Christus maa boe formedelst Troen i Eders Hjerter,"],[3,18,"saa at I, rodfæstede og grundfæstede i Kjærlighed, kunne formaae at begribe alle de Hellige baade Breden og Længden, og Dybden og Høiden,","saa at I, rodfæstede og grundfæstede i Kjærlighed, kunne formaae at begribe alle de Hellige baade Breden og Længden, og Dybden og Høiden,"],[3,19,"og kjende Christi Kjærlighed, som overgaaer al Kundskab, at I kunne opfyldes af al Guds Fylde.","og kjende Christi Kjærlighed, som overgaaer al Kundskab, at I kunne opfyldes af al Guds Fylde."],[3,20,"Men ham, som formaaer over alle Ting at gjøre langt overflødigere, end hvad vi bede eller forstaae, efter den Magt, som teer sig kraftig i os,","Men ham, som formaaer over alle Ting at gjøre langt overflødigere, end hvad vi bede eller forstaae, efter den Magt, som teer sig kraftig i os,"],[3,21,"han være Ære i Menigheden ved Christus Jesus, gjennem alle Slægter, i alle Evigheder! Amen.","han være Ære i Menigheden ved Christus Jesus, gjennem alle Slægter, i alle Evigheder! Amen."],[4,1,"Jeg formaner Eder derfor, jeg, den Bundne i Herren, at I vandre værdigen det Kald, med hvilket I ere kaldte,","Jeg formaner Eder derfor, jeg, den Bundne i Herren, at I vandre værdigen det Kald, med hvilket I ere kaldte,"],[4,2,"med al Ydmyghed og Sagtmodighed, med Langmodighed, saa I fordrage hverandre i Kjærlighed,","med al Ydmyghed og Sagtmodighed, med Langmodighed, saa I fordrage hverandre i Kjærlighed,"],[4,3,"og beflitte Eder paa at bevare Aandens Eenhed i Fredens Baand;","og beflitte Eder paa at bevare Aandens Eenhed i Fredens Baand;"],[4,4,"eet Legeme og een Aand, ligesom I og ere Kaldte til eet Haab i Eders Kald;","eet Legeme og een Aand, ligesom I og ere Kaldte til eet Haab i Eders Kald;"],[4,5,"een Herre, een Tro, een Daab,","een Herre, een Tro, een Daab,"],[4,6,"een Gud og Alles Fader, som ere over Alle, og ved Alle, og i Eder alle!","een Gud og Alles Fader, som ere over Alle, og ved Alle, og i Eder alle!"],[4,7,"Men enhver af os er Naaden given efter Christi Gaves Maal.","Men enhver af os er Naaden given efter Christi Gaves Maal."],[4,8,"Derfor siger Skriften: han opfoer til det Høie, bortførte Fanger, og gav Menneskene Gaver.","Derfor siger Skriften: han opfoer til det Høie, bortførte Fanger, og gav Menneskene Gaver."],[4,9,"Men dette: han opfoer, hvad er det, uden at han og først nedfoer til Jordens lave Egne.","Men dette: han opfoer, hvad er det, uden at han og først nedfoer til Jordens lave Egne."],[4,10,"Den, som nedfoer, er den Samme, som og opfoer langt over alle Himle, at han skulde fylde alle Ting.","Den, som nedfoer, er den Samme, som og opfoer langt over alle Himle, at han skulde fylde alle Ting."],[4,11,"Og han beskikkede Nogle til Apostler, Nogle til Propheter, Nogle til Evangelister, Nogle til Hyrder og Lærere,","Og han beskikkede Nogle til Apostler, Nogle til Propheter, Nogle til Evangelister, Nogle til Hyrder og Lærere,"],[4,12,"til de Helliges fuldkomne Beredelse, til Embedets Forvaltning, til Christi Legemes Opbyggelse,","til de Helliges fuldkomne Beredelse, til Embedets Forvaltning, til Christi Legemes Opbyggelse,"],[4,13,"indtil vi alle naae til Eenhed i Troen og Guds Søns Erkjendelse, til Mands Modenhed, til Christi Fyldes voxne Alder,","indtil vi alle naae til Eenhed i Troen og Guds Søns Erkjendelse, til Mands Modenhed, til Christi Fyldes voxne Alder,"],[4,14,"at vi ikke mere skulle være Børn og lade os tumle som Bølger og omdrive af enhver Lærdoms Veir, ved Menneskenes Spil, ved Trædskhed og Forførelsens Kunstgreb;","at vi ikke mere skulle være Børn og lade os tumle som Bølger og omdrive af enhver Lærdoms Veir, ved Menneskenes Spil, ved Trædskhed og Forførelsens Kunstgreb;"],[4,15,"men at vi, Sandheden troe udi Kjærlighed, skulle i alle Maader opvoxe til ham, som er Hovedet, til Christus,","men at vi, Sandheden troe udi Kjærlighed, skulle i alle Maader opvoxe til ham, som er Hovedet, til Christus,"],[4,16,"af hvem det ganske Legeme, sammenføiet og sammenheftet ved alle Forbindelsens Led, efter ethvert Lems tilmaalte Kraft, drager sin Næring til Fremvæxt i Kjærlighed.","af hvem det ganske Legeme, sammenføiet og sammenheftet ved alle Forbindelsens Led, efter ethvert Lems tilmaalte Kraft, drager sin Næring til Fremvæxt i Kjærlighed."],[4,17,"Dette siger jeg da og vidner i Herren, at I skulle ikke mere vandre, som de øvrige Hedninger vandre i deres Sinds Forfængelighed,","Dette siger jeg da og vidner i Herren, at I skulle ikke mere vandre, som de øvrige Hedninger vandre i deres Sinds Forfængelighed,"],[4,18,"formørkede i Forstanden, fremmedgjorte fra Guds Liv formedelst den Vankundighed, som er i dem, formedelst deres Hjertes Forhærdelse,","formørkede i Forstanden, fremmedgjorte fra Guds Liv formedelst den Vankundighed, som er i dem, formedelst deres Hjertes Forhærdelse,"],[4,19,"hvilke, følesløse, have hengivet sig til Uteerlighed, til al Urenheds Bedrift, for Vindings Skyld.","hvilke, følesløse, have hengivet sig til Uteerlighed, til al Urenheds Bedrift, for Vindings Skyld."],[4,20,"Men I have ikke saaledes lært Christus,","Men I have ikke saaledes lært Christus,"],[4,21,"dersom I ellers have hørt om ham, og ere oplærte i ham saaledes, som Sandheden er i Jesus:","dersom I ellers have hørt om ham, og ere oplærte i ham saaledes, som Sandheden er i Jesus:"],[4,22,"at I skulle aflægge det gamle Menneske efter den forrige Omgængelse, som fordærves ved bedragelige Lyster;","at I skulle aflægge det gamle Menneske efter den forrige Omgængelse, som fordærves ved bedragelige Lyster;"],[4,23,"men fornyes i Eders Sinds Aand,","men fornyes i Eders Sinds Aand,"],[4,24,"og iføre det nye Menneske, som er skabt efter Gud i Sandhedens Retfærdighed og Hellighed.","og iføre det nye Menneske, som er skabt efter Gud i Sandhedens Retfærdighed og Hellighed."],[4,25,"Derfor aflægger Løgn og taler Sandhed, hver med sin Næste, efterdi vi ere hverandres Lemmer.","Derfor aflægger Løgn og taler Sandhed, hver med sin Næste, efterdi vi ere hverandres Lemmer."],[4,26,"Blive I vrede, da synder ikke; Solen gaae ikke ned over Eders Fortørnelse;","Blive I vrede, da synder ikke; Solen gaae ikke ned over Eders Fortørnelse;"],[4,27,"giver ikke heller Djævelen Rum!","giver ikke heller Djævelen Rum!"],[4,28,"Den, som stjal, stjæle ikke fremdeles, men arbeide heller og gjøre noget Godt med Hænderne, paa det han kan have at meddele dem, som have behov.","Den, som stjal, stjæle ikke fremdeles, men arbeide heller og gjøre noget Godt med Hænderne, paa det han kan have at meddele dem, som have behov."],[4,29,"Ingen raadden Snak udgaae af Eders Mund, men saadan Tale, som er god til fornøden Opbyggelse, at den kan skaffe dem Naade, som høre derpaa;","Ingen raadden Snak udgaae af Eders Mund, men saadan Tale, som er god til fornøden Opbyggelse, at den kan skaffe dem Naade, som høre derpaa;"],[4,30,"og bedrøver ikke Guds hellige Aand, med hvilken I ere beseglede til Forløsningens Dag.","og bedrøver ikke Guds hellige Aand, med hvilken I ere beseglede til Forløsningens Dag."],[4,31,"Al Bitterhed og Hidsighed og Vrede og Skrigen og Bespottelse blive langt fra Eder, med al Ondskab.","Al Bitterhed og Hidsighed og Vrede og Skrigen og Bespottelse blive langt fra Eder, med al Ondskab."],[4,32,"Men værer velvillige mod hverandre, barmhjertige, tilgivende hverandre, ligesom og Gud haver tilgivet Eder i Christus.","Men værer velvillige mod hverandre, barmhjertige, tilgivende hverandre, ligesom og Gud haver tilgivet Eder i Christus."],[5,1,"Værer derfor Guds Efterfølgere som elskelige Børn,","Værer derfor Guds Efterfølgere som elskelige Børn,"],[5,2,"og omgaaes i Kjærlighed, ligesom og Christus elskede os og gav sig selv hen for os til en Gave, et Slagtoffer, Gud til en velbehagelig Lugt.","og omgaaes i Kjærlighed, ligesom og Christus elskede os og gav sig selv hen for os til en Gave, et Slagtoffer, Gud til en velbehagelig Lugt."],[5,3,"Men Horeri og al Ureenhed eller Gjerrighed nævnes end ikke iblandt Eder, som det sømmer de Hellige,","Men Horeri og al Ureenhed eller Gjerrighed nævnes end ikke iblandt Eder, som det sømmer de Hellige,"],[5,4,"og ublu Væsen og gjekkelig Snak eller letfærdig Skjemt, som alt er utilbørligt, men hellere Taksigelse.","og ublu Væsen og gjekkelig Snak eller letfærdig Skjemt, som alt er utilbørligt, men hellere Taksigelse."],[5,5,"Thi dette vide I, at ingen Skjørlevner eller Ureen eller Gjerrig, hvilken er en Afgudsdyrker, haver Arv i Christi og Guds Rige.","Thi dette vide I, at ingen Skjørlevner eller Ureen eller Gjerrig, hvilken er en Afgudsdyrker, haver Arv i Christi og Guds Rige."],[5,6,"Ingen forføre Eder med forfængelige Ord; thi for Saadant kommer Guds Vrede over Vantroens Børn.","Ingen forføre Eder med forfængelige Ord; thi for Saadant kommer Guds Vrede over Vantroens Børn."],[5,7,"Derfor vorder ikke deelagtige med dem.","Derfor vorder ikke deelagtige med dem."],[5,8,"Thi I vare forhen Mørkhed, men nu ere I et Lys i Herren; omgaaes som Lysets Børn,","Thi I vare forhen Mørkhed, men nu ere I et Lys i Herren; omgaaes som Lysets Børn,"],[5,9,"(men Lysets Frugt viser sig i al Godhed og Retfærdighed og Sandhed),","(men Lysets Frugt viser sig i al Godhed og Retfærdighed og Sandhed),"],[5,10,"saa I prøve, hvad som er velbehageligt for Herren.","saa I prøve, hvad som er velbehageligt for Herren."],[5,11,"Og haver ikke Samfund med Mørkets ufrugtbare Gjerninger, men straffer dem hellere.","Og haver ikke Samfund med Mørkets ufrugtbare Gjerninger, men straffer dem hellere."],[5,12,"Thi hvad der lønligen bedrives af dem, er skammeligt endog at sige.","Thi hvad der lønligen bedrives af dem, er skammeligt endog at sige."],[5,13,"Men alt dette, naar det straffes, aabenbares ved Lyset; thi alt det, som aabenbarer, er Lys.","Men alt dette, naar det straffes, aabenbares ved Lyset; thi alt det, som aabenbarer, er Lys."],[5,14,"Derfor hedder det: vaagn op, du som sover, og staa op fra de Døde, og Christus skal lyse for dig!","Derfor hedder det: vaagn op, du som sover, og staa op fra de Døde, og Christus skal lyse for dig!"],[5,15,"Seer derfor til, at I omgaaes varligen, ikke som Uvise, men som Vise,","Seer derfor til, at I omgaaes varligen, ikke som Uvise, men som Vise,"],[5,16,"og kjøber den beleilige Tid, fordi Dagene ere onde.","og kjøber den beleilige Tid, fordi Dagene ere onde."],[5,17,"Derfor værer ikke uforstandige, men som de, der skjønne, hvad Herrens Villie er.","Derfor værer ikke uforstandige, men som de, der skjønne, hvad Herrens Villie er."],[5,18,"Og drikker Eder ikke drukne af Viin, i hvilket der er Ryggesløshed, men bliver fyldte af Aanden,","Og drikker Eder ikke drukne af Viin, i hvilket der er Ryggesløshed, men bliver fyldte af Aanden,"],[5,19,"og taler hverandre til med Psalmer og Lovsange og aandelige Viser, og synger og leger for Herren i Eders Hjerte,","og taler hverandre til med Psalmer og Lovsange og aandelige Viser, og synger og leger for Herren i Eders Hjerte,"],[5,20,"og siger altid Gud og Faderen Tak for alle Ting i vor Herres Jesu Christi Navn,","og siger altid Gud og Faderen Tak for alle Ting i vor Herres Jesu Christi Navn,"],[5,21,"og værer hverandre underdanige i Guds Frygt.","og værer hverandre underdanige i Guds Frygt."],[5,22,"I Kvinder! værer Eders egne Mænd underdanige, som Herren;","I Kvinder! værer Eders egne Mænd underdanige, som Herren;"],[5,23,"thi Manden er Kvindens Hoved, ligesom og Christus er Menighedens Hoved, og han er sit Legems Saliggjører.","thi Manden er Kvindens Hoved, ligesom og Christus er Menighedens Hoved, og han er sit Legems Saliggjører."],[5,24,"Men ligesom Menigheden er Christus underdanig, saaledes skulle og Kvinderne være deres egne Mænd underdanige i alle Ting.","Men ligesom Menigheden er Christus underdanig, saaledes skulle og Kvinderne være deres egne Mænd underdanige i alle Ting."],[5,25,"I Mænd! elsker Eders Hustruer, ligesom og Christus elskede Menigheden og hengav sig selv for den,","I Mænd! elsker Eders Hustruer, ligesom og Christus elskede Menigheden og hengav sig selv for den,"],[5,26,"paa det han kunde hellige den, og han rensede den formedelst Vandbadet ved Ordet,","paa det han kunde hellige den, og han rensede den formedelst Vandbadet ved Ordet,"],[5,27,"at han maatte fremstille sig den, en herlig Menighed, som ikke haver Plet eller Rynke eller noget deslige, men at den maatte være hellig og ustraffelig.","at han maatte fremstille sig den, en herlig Menighed, som ikke haver Plet eller Rynke eller noget deslige, men at den maatte være hellig og ustraffelig."],[5,28,"Saaledes ere Mændene skyldige at elske deres Hustruer, som deres egne Legemer; hvo som elsker sin Hustru, elsker sig selv.","Saaledes ere Mændene skyldige at elske deres Hustruer, som deres egne Legemer; hvo som elsker sin Hustru, elsker sig selv."],[5,29,"Ingen hadede jo nogensinde sit eget Kjød, men føder og vederkvæger det, ligesom og Herren Menigheden.","Ingen hadede jo nogensinde sit eget Kjød, men føder og vederkvæger det, ligesom og Herren Menigheden."],[5,30,"Thi vi ere hans Legemes Lemmer, af hans Kjød og af hans Been.","Thi vi ere hans Legemes Lemmer, af hans Kjød og af hans Been."],[5,31,"Derfor skal Manden forlade sin Fader og Moder og blive fast hos sin Hustru, og de To skulle være eet Kjød.","Derfor skal Manden forlade sin Fader og Moder og blive fast hos sin Hustru, og de To skulle være eet Kjød."],[5,32,"Denne Hemmelighed er stor; jeg taler nemlig om Herren og Menigheden.","Denne Hemmelighed er stor; jeg taler nemlig om Herren og Menigheden."],[5,33,"Dog I ogsaa, hver især elske sin Hustru som sig selv; men Hustruen have Ærefrygt for Manden.","Dog I ogsaa, hver især elske sin Hustru som sig selv; men Hustruen have Ærefrygt for Manden."],[6,1,"I Børn! lyder Eders Forældre i Herren, thi dette er ret.","I Børn! lyder Eders Forældre i Herren, thi dette er ret."],[6,2,"Ær din Fader og Moder, (hvilket er det første Bud med Forjættelse),","Ær din Fader og Moder, (hvilket er det første Bud med Forjættelse),"],[6,3,"at det maa gaae dig vel, og du maa længe leve paa Jorden.","at det maa gaae dig vel, og du maa længe leve paa Jorden."],[6,4,"Og I Fædre! opirrer ikke Eders Børn, men opføder dem i Tugt og Herrens Formaning.","Og I Fædre! opirrer ikke Eders Børn, men opføder dem i Tugt og Herrens Formaning."],[6,5,"I Tjenere! lyder Eders Herrer efter Kjødet med Frygt og Bæven, i Eders Hjertes Enfoldighed, som Christus;","I Tjenere! lyder Eders Herrer efter Kjødet med Frygt og Bæven, i Eders Hjertes Enfoldighed, som Christus;"],[6,6,"ikke med Øientjeneste som de, der ville tækkes Menneskene, men som Christi Tjenere, saa I gjøre Guds Villie af Hjertet,","ikke med Øientjeneste som de, der ville tækkes Menneskene, men som Christi Tjenere, saa I gjøre Guds Villie af Hjertet,"],[6,7,"tjenende med Velvillighed Herren, og ikke Mennesker;","tjenende med Velvillighed Herren, og ikke Mennesker;"],[6,8,"vidende, at hvad Godt enhver gjør, det skal han gjengjeldes af Herren, hvad heller han er Tjener eller Fri.","vidende, at hvad Godt enhver gjør, det skal han gjengjeldes af Herren, hvad heller han er Tjener eller Fri."],[6,9,"Og I Herrer! gjører det Samme mod dem, og lader Trusel fare, vidende at ogsaa I selv have Eders Herre i Himlene, og Persons Anseelse er ikke hos ham.","Og I Herrer! gjører det Samme mod dem, og lader Trusel fare, vidende at ogsaa I selv have Eders Herre i Himlene, og Persons Anseelse er ikke hos ham."],[6,10,"Iøvrigt, mine Brødre, vorder stærke i Herren og i hans Vældes Kraft!","Iøvrigt, mine Brødre, vorder stærke i Herren og i hans Vældes Kraft!"],[6,11,"Ifører Guds fulde Rustning, at I kunne være mægtige til at staae imod Djævelens snedige Anløb.","Ifører Guds fulde Rustning, at I kunne være mægtige til at staae imod Djævelens snedige Anløb."],[6,12,"Thi vi have ikke Kamp mod Kjød og Blod, men mod Fyrstendømmer og Magter, mod Verdens Herrer, som regjere i denne Tids Mørke, mod Ondskabens aandelige Hær under Himmelen,","Thi vi have ikke Kamp mod Kjød og Blod, men mod Fyrstendømmer og Magter, mod Verdens Herrer, som regjere i denne Tids Mørke, mod Ondskabens aandelige Hær under Himmelen,"],[6,13,"Derfor tager Guds fulde Rustning paa, at I kunne gjøre Modstand paa den onde Dag, og bestaae, efter at have overvundet Alt.","Derfor tager Guds fulde Rustning paa, at I kunne gjøre Modstand paa den onde Dag, og bestaae, efter at have overvundet Alt."],[6,14,"Saa staaer da omgjordede om Eders Lænder med Sandhed, og iførte Retfærdigheds Pantser,","Saa staaer da omgjordede om Eders Lænder med Sandhed, og iførte Retfærdigheds Pantser,"],[6,15,"Fødderne ombundne med Færdighed i Fredens Evangelium;","Fødderne ombundne med Færdighed i Fredens Evangelium;"],[6,16,"for Alting griber Troens Skjold, med hvilket I skulle kunne slukke alle den Ondes gloende Pile,","for Alting griber Troens Skjold, med hvilket I skulle kunne slukke alle den Ondes gloende Pile,"],[6,17,"og tager Saliggjørelsens Hjelm og Aandens Sværd, som er Guds Ord;","og tager Saliggjørelsens Hjelm og Aandens Sværd, som er Guds Ord;"],[6,18,"bedende til hver Tid i Aanden med al Bøn og Begjering, aarvaagne til det Samme med al Varagtighed og Bøn for alle de Hellige,","bedende til hver Tid i Aanden med al Bøn og Begjering, aarvaagne til det Samme med al Varagtighed og Bøn for alle de Hellige,"],[6,19,"ogsaa for mig, at min Mund maa oplades, og Ordet maa gives mig til at kundgjøre med Frimodighed Evangeliums Hemmelighed,","ogsaa for mig, at min Mund maa oplades, og Ordet maa gives mig til at kundgjøre med Frimodighed Evangeliums Hemmelighed,"],[6,20,"for hvis Skyld jeg er et Sendebud i Lænker, at jeg maa tale med Frimodighed derudi, som mig bør at tale.","for hvis Skyld jeg er et Sendebud i Lænker, at jeg maa tale med Frimodighed derudi, som mig bør at tale."],[6,21,"Men at ogsaa I skulle vide min Tilstand, hvorledes det gaaer mig, da skal Tychicus, den elskelige Broder og troe Tjener i Herren, kundgjøre Eder Alt;","Men at ogsaa I skulle vide min Tilstand, hvorledes det gaaer mig, da skal Tychicus, den elskelige Broder og troe Tjener i Herren, kundgjøre Eder Alt;"],[6,22,"hvem jeg haver sendt til Eder, just for at I skulle vide, hvorledes det staaer til hos os, og at han skal trøste Eders Hjerter.","hvem jeg haver sendt til Eder, just for at I skulle vide, hvorledes det staaer til hos os, og at han skal trøste Eders Hjerter."],[6,23,"Fred med Brødrene og Kjærlighed med Tro, fra Gud Fader og den Herre Jesus Christus.","Fred med Brødrene og Kjærlighed med Tro, fra Gud Fader og den Herre Jesus Christus."],[6,24,"Naaden være med alle dem, som elske vor Herre Jesus Christus i Uforkrænkelighed! Amen.","Naaden være med alle dem, som elske vor Herre Jesus Christus i Uforkrænkelighed! Amen."]],"epo-londona":[[1,1,"Paŭlo, apostolo de Jesuo Kristo per la volo de Dio, al la sanktuloj, kiuj estas en Efeso, kaj al la fideluloj en Kristo Jesuo:","Paŭlo, apostolo de Jesuo Kristo per la volo de Dio, al la sanktuloj, kiuj estas en Efeso, kaj al la fideluloj en Kristo Jesuo:"],[1,2,"Graco estu al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo.","Graco estu al vi kaj paco de Dio, nia Patro, kaj de la Sinjoro Jesuo Kristo."],[1,3,"Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, kiu benis nin per ĉia beno spirita en la ĉielejoj en Kristo;","Benata estu la Dio kaj Patro de nia Sinjoro Jesuo Kristo, kiu benis nin per ĉia beno spirita en la ĉielejoj en Kristo;"],[1,4,"kiel Li elektis nin en li antaŭ la fondo de la mondo, por ke ni estu sanktaj kaj senmakulaj antaŭ Li en amo;","kiel Li elektis nin en li antaŭ la fondo de la mondo, por ke ni estu sanktaj kaj senmakulaj antaŭ Li en amo;"],[1,5,"antaŭdestininte nin por filadopto per Jesuo Kristo al Si mem, laŭ la aprobo de Sia volo,","antaŭdestininte nin por filadopto per Jesuo Kristo al Si mem, laŭ la aprobo de Sia volo,"],[1,6,"al la laŭdo de la gloro de Lia graco, per kiu Li favoris nin en la Amata;","al la laŭdo de la gloro de Lia graco, per kiu Li favoris nin en la Amata;"],[1,7,"en kiu ni havas la elaĉeton per lia sango, la pardonon de niaj pekoj, laŭ la riĉo de lia graco,","en kiu ni havas la elaĉeton per lia sango, la pardonon de niaj pekoj, laŭ la riĉo de lia graco,"],[1,8,"kiun li abundigis al ni en ĉia saĝeco kaj prudento,","kiun li abundigis al ni en ĉia saĝeco kaj prudento,"],[1,9,"sciiginte al ni la misteron de Lia volo, laŭ Lia bonvolo, kiun Li antaŭdecidis en li,","sciiginte al ni la misteron de Lia volo, laŭ Lia bonvolo, kiun Li antaŭdecidis en li,"],[1,10,"por dispono en la pleneco de la tempo, por sumigi en Kristo ĉion, kio estas en la ĉieloj kaj sur la tero;","por dispono en la pleneco de la tempo, por sumigi en Kristo ĉion, kio estas en la ĉieloj kaj sur la tero;"],[1,11,"en li, en kiu ni fariĝis heredaĵo, destinite laŭ la antaŭdecido de Tiu, kiu ĉion faras laŭ la intenco de Sia volo;","en li, en kiu ni fariĝis heredaĵo, destinite laŭ la antaŭdecido de Tiu, kiu ĉion faras laŭ la intenco de Sia volo;"],[1,12,"por ke ni estu por la laŭdo de Lia gloro, ni, kiuj antaŭe esperis en Kristo;","por ke ni estu por la laŭdo de Lia gloro, ni, kiuj antaŭe esperis en Kristo;"],[1,13,"en kiu vi ankaŭ esperas, aŭdinte la vorton de la vero, la evangelion de via savo; al kiu ankaŭ kredinte, vi estas sigelitaj per la Sankta Spirito de promeso,","en kiu vi ankaŭ esperas, aŭdinte la vorton de la vero, la evangelion de via savo; al kiu ankaŭ kredinte, vi estas sigelitaj per la Sankta Spirito de promeso,"],[1,14,"kiu estas antaŭgarantiaĵo de nia heredaĵo, por la elaĉeto de la posedaĵo, por laŭdo de Lia gloro.","kiu estas antaŭgarantiaĵo de nia heredaĵo, por la elaĉeto de la posedaĵo, por laŭdo de Lia gloro."],[1,15,"Pro tio mi ankaŭ, aŭdinte pri via fido al la Sinjoro Jesuo, kaj via amo al ĉiuj sanktuloj,","Pro tio mi ankaŭ, aŭdinte pri via fido al la Sinjoro Jesuo, kaj via amo al ĉiuj sanktuloj,"],[1,16,"ne ĉesas danki pro vi, vin nomante en miaj preĝoj;","ne ĉesas danki pro vi, vin nomante en miaj preĝoj;"],[1,17,"por ke la Dio de nia Sinjoro Jesuo Kristo, la Patro de gloro, donu al vi spiriton de saĝeco kaj malkaŝo en la konado de Li;","por ke la Dio de nia Sinjoro Jesuo Kristo, la Patro de gloro, donu al vi spiriton de saĝeco kaj malkaŝo en la konado de Li;"],[1,18,"dum la okuloj de via koro estas lumigataj, por ke vi sciu, kia estas la espero de Lia voko, kaj kia la riĉeco de la gloro de Lia heredaĵo en la sanktuloj,","dum la okuloj de via koro estas lumigataj, por ke vi sciu, kia estas la espero de Lia voko, kaj kia la riĉeco de la gloro de Lia heredaĵo en la sanktuloj,"],[1,19,"kaj kia la supermezura grandeco de Lia potenco al ni, kiuj kredas, laŭ la energio de la efikeco de Lia forto,","kaj kia la supermezura grandeco de Lia potenco al ni, kiuj kredas, laŭ la energio de la efikeco de Lia forto,"],[1,20,"kiun Li faris en Kristo, relevante lin el la mortintoj, kaj sidigante lin dekstre de Li en la ĉieloj,","kiun Li faris en Kristo, relevante lin el la mortintoj, kaj sidigante lin dekstre de Li en la ĉieloj,"],[1,21,"multe super ĉiu reganto kaj aŭtoritato kaj potenco kaj regeco, kaj ĉiu nomo nomata, ne nur en ĉi tiu mondo, sed ankaŭ en la estonta;","multe super ĉiu reganto kaj aŭtoritato kaj potenco kaj regeco, kaj ĉiu nomo nomata, ne nur en ĉi tiu mondo, sed ankaŭ en la estonta;"],[1,22,"kaj ĉion Li metis sub liajn piedojn, kaj donis lin kiel kapon super ĉio por la eklezio,","kaj ĉion Li metis sub liajn piedojn, kaj donis lin kiel kapon super ĉio por la eklezio,"],[1,23,"kiu estas lia korpo, la pleneco de Tiu, kiu plenigas ĉion en ĉio.","kiu estas lia korpo, la pleneco de Tiu, kiu plenigas ĉion en ĉio."],[2,1,"Kaj vin li vivigis, kiam vi estis malvivaj per eraroj kaj pekoj,","Kaj vin li vivigis, kiam vi estis malvivaj per eraroj kaj pekoj,"],[2,2,"en kiuj vi iam iradis laŭ la vojo de ĉi tiu mondo, laŭ la estro de la potenco de la aero, de la spirito, kiu nun energias en la filoj de malobeo;","en kiuj vi iam iradis laŭ la vojo de ĉi tiu mondo, laŭ la estro de la potenco de la aero, de la spirito, kiu nun energias en la filoj de malobeo;"],[2,3,"inter kiuj ni ĉiuj iam ankaŭ vivis, plenumante la dezirojn de nia karno, farante la volojn de la karno kaj de la menso, kaj ni estis laŭ naturo infanoj de kolerego, kiel ankaŭ la aliaj.","inter kiuj ni ĉiuj iam ankaŭ vivis, plenumante la dezirojn de nia karno, farante la volojn de la karno kaj de la menso, kaj ni estis laŭ naturo infanoj de kolerego, kiel ankaŭ la aliaj."],[2,4,"Sed Dio, estante riĉa en kompateco, pro Sia granda amo, per kiu Li amis nin,","Sed Dio, estante riĉa en kompateco, pro Sia granda amo, per kiu Li amis nin,"],[2,5,"eĉ kiam ni estis malvivaj en niaj eraroj, nin vivigis en Kristo (per graco vi saviĝis),","eĉ kiam ni estis malvivaj en niaj eraroj, nin vivigis en Kristo (per graco vi saviĝis),"],[2,6,"kaj nin levis, kaj nin kunsidigis en la ĉielejoj en Kristo Jesuo;","kaj nin levis, kaj nin kunsidigis en la ĉielejoj en Kristo Jesuo;"],[2,7,"por montri en la mondaĝoj estontaj la superabundan riĉecon de Sia graco en korfavoro al ni en Kristo Jesuo:","por montri en la mondaĝoj estontaj la superabundan riĉecon de Sia graco en korfavoro al ni en Kristo Jesuo:"],[2,8,"ĉar per graco vi saviĝis per fido; ne per vi mem: ĝi estas dono de Dio;","ĉar per graco vi saviĝis per fido; ne per vi mem: ĝi estas dono de Dio;"],[2,9,"ne el faroj, por ke neniu fanfaronu.","ne el faroj, por ke neniu fanfaronu."],[2,10,"Ĉar ni estas Lia faritaĵo, kreitaj en Kristo Jesuo por bonaj faroj, kiujn antaŭaranĝis Dio, por ke ni iradu en ili.","Ĉar ni estas Lia faritaĵo, kreitaj en Kristo Jesuo por bonaj faroj, kiujn antaŭaranĝis Dio, por ke ni iradu en ili."],[2,11,"Kaj pro tio rememoru, ke iam vi, nacianoj laŭ la karno, nomataj la Necirkumcido ĉe la tiel nomata Cirkumcido, mane farita sur la karno —","Kaj pro tio rememoru, ke iam vi, nacianoj laŭ la karno, nomataj la Necirkumcido ĉe la tiel nomata Cirkumcido, mane farita sur la karno —"],[2,12,"ke vi estis tiam sen Kristo, fremdigitaj for de la komunumo de Izrael, kaj eksteruloj de la interligoj de la promeso, esperon ne havantaj kaj sen Dio en la mondo.","ke vi estis tiam sen Kristo, fremdigitaj for de la komunumo de Izrael, kaj eksteruloj de la interligoj de la promeso, esperon ne havantaj kaj sen Dio en la mondo."],[2,13,"Sed nun en Kristo Jesuo vi, iam malproksimaj, proksimiĝis en la sango de Kristo.","Sed nun en Kristo Jesuo vi, iam malproksimaj, proksimiĝis en la sango de Kristo."],[2,14,"Ĉar nia paco estas li, kiu unuigis ambaŭ kaj rompis la intermuron de disigo,","Ĉar nia paco estas li, kiu unuigis ambaŭ kaj rompis la intermuron de disigo,"],[2,15,"en sia karno neniiginte la malamon, la leĝon de ordonoj en dekretoj; por krei en si el la du unu novan homon, tiel farante pacon;","en sia karno neniiginte la malamon, la leĝon de ordonoj en dekretoj; por krei en si el la du unu novan homon, tiel farante pacon;"],[2,16,"kaj por kunakordigi ambaŭ en unu korpo al Dio per la kruco, mortiginte per tio la malamon;","kaj por kunakordigi ambaŭ en unu korpo al Dio per la kruco, mortiginte per tio la malamon;"],[2,17,"kaj li venis kaj predikis pacon al vi malproksimaj kaj al la proksimaj;","kaj li venis kaj predikis pacon al vi malproksimaj kaj al la proksimaj;"],[2,18,"ĉar per li ni ambaŭ havas en unu Spirito alkondukon al la Patro.","ĉar per li ni ambaŭ havas en unu Spirito alkondukon al la Patro."],[2,19,"Sekve vi jam estas ne fremduloj kaj pasloĝantoj, sed samregnanoj kun la sanktuloj, kaj el la domanaro de Dio,","Sekve vi jam estas ne fremduloj kaj pasloĝantoj, sed samregnanoj kun la sanktuloj, kaj el la domanaro de Dio,"],[2,20,"konstruitaj sur la fundamento de la apostoloj kaj profetoj, kies bazangula ŝtono estas Kristo Jesuo mem;","konstruitaj sur la fundamento de la apostoloj kaj profetoj, kies bazangula ŝtono estas Kristo Jesuo mem;"],[2,21,"en kiu ĉiu aparta konstruaĵo, bone kunigita, kreske fariĝas sankta templo en Kristo;","en kiu ĉiu aparta konstruaĵo, bone kunigita, kreske fariĝas sankta templo en Kristo;"],[2,22,"en kiu vi ankaŭ estas kunkonstruitaj por sanktejo de Dio en la Spirito.","en kiu vi ankaŭ estas kunkonstruitaj por sanktejo de Dio en la Spirito."],[3,1,"Pro tio mi, Paŭlo, malliberulo de Kristo Jesuo por vi nacianoj,","Pro tio mi, Paŭlo, malliberulo de Kristo Jesuo por vi nacianoj,"],[3,2,"se vi aŭdis pri la dispono de tiu graco de Dio, kiu estas donita al mi por vi,","se vi aŭdis pri la dispono de tiu graco de Dio, kiu estas donita al mi por vi,"],[3,3,"ke per malkaŝo la mistero estas sciigita al mi, kiel mi jam antaŭe mallonge skribis,","ke per malkaŝo la mistero estas sciigita al mi, kiel mi jam antaŭe mallonge skribis,"],[3,4,"per kio vi povas rimarki, dum vi legas, mian komprenon en la mistero de Kristo,","per kio vi povas rimarki, dum vi legas, mian komprenon en la mistero de Kristo,"],[3,5,"kiu en aliaj generacioj ne estis sciigita al la homidoj, kiel ĝi nun malkaŝiĝis al liaj sanktaj apostoloj kaj profetoj en la Spirito,","kiu en aliaj generacioj ne estis sciigita al la homidoj, kiel ĝi nun malkaŝiĝis al liaj sanktaj apostoloj kaj profetoj en la Spirito,"],[3,6,"ke la nacianoj estas kunheredantoj, kaj samkorpanoj, kaj partoprenantoj en la promeso en Kristo Jesuo per la evangelio,","ke la nacianoj estas kunheredantoj, kaj samkorpanoj, kaj partoprenantoj en la promeso en Kristo Jesuo per la evangelio,"],[3,7,"al kiu mi fariĝis servanto laŭ la dono de la graco de Dio, donita al mi laŭ la energio de Lia potenco.","al kiu mi fariĝis servanto laŭ la dono de la graco de Dio, donita al mi laŭ la energio de Lia potenco."],[3,8,"Al mi, kiu estas malpli ol la malplej granda el ĉiuj sanktuloj, ĉi tiu graco estas donita, por ke mi prediku inter la nacioj la neesploreblan riĉon de Kristo;","Al mi, kiu estas malpli ol la malplej granda el ĉiuj sanktuloj, ĉi tiu graco estas donita, por ke mi prediku inter la nacioj la neesploreblan riĉon de Kristo;"],[3,9,"kaj por ke mi klarigu al ĉiuj, kia estas la dispono de la mistero kaŝita tra ĉiuj mondaĝoj en Dio, kiu kreis ĉion;","kaj por ke mi klarigu al ĉiuj, kia estas la dispono de la mistero kaŝita tra ĉiuj mondaĝoj en Dio, kiu kreis ĉion;"],[3,10,"por ke nun konatiĝu al la regantoj kaj aŭtoritatoj en la ĉielejoj, per la eklezio, la multobla saĝeco de Dio,","por ke nun konatiĝu al la regantoj kaj aŭtoritatoj en la ĉielejoj, per la eklezio, la multobla saĝeco de Dio,"],[3,11,"laŭ la eterna decido, kiun Li faris en Kristo Jesuo, nia Sinjoro;","laŭ la eterna decido, kiun Li faris en Kristo Jesuo, nia Sinjoro;"],[3,12,"en kiu ni havas kuraĝon kaj alkondukon en fidado per nia fido al li.","en kiu ni havas kuraĝon kaj alkondukon en fidado per nia fido al li."],[3,13,"Pro tio mi petas, ke vi ne senfortiĝu pro miaj suferoj por vi, kiuj estas via gloro.","Pro tio mi petas, ke vi ne senfortiĝu pro miaj suferoj por vi, kiuj estas via gloro."],[3,14,"Pro tio mi fleksas miajn genuojn antaŭ la Patro,","Pro tio mi fleksas miajn genuojn antaŭ la Patro,"],[3,15,"el kiu ĉiu familio, en la ĉielo kaj sur la tero, estas nomata,","el kiu ĉiu familio, en la ĉielo kaj sur la tero, estas nomata,"],[3,16,"por ke Li donu al vi, laŭ la riĉo de Sia gloro, ke vi estu potence fortigitaj en la interna homo, per Lia Spirito;","por ke Li donu al vi, laŭ la riĉo de Sia gloro, ke vi estu potence fortigitaj en la interna homo, per Lia Spirito;"],[3,17,"por ke Kristo loĝu per fido en viaj koroj; tiel, ke vi, enradikigite kaj bazite en amo,","por ke Kristo loĝu per fido en viaj koroj; tiel, ke vi, enradikigite kaj bazite en amo,"],[3,18,"kapabliĝu kun ĉiuj sanktuloj kompreni, kio estas la larĝeco kaj longeco kaj alteco kaj profundeco,","kapabliĝu kun ĉiuj sanktuloj kompreni, kio estas la larĝeco kaj longeco kaj alteco kaj profundeco,"],[3,19,"kaj scii la amon de Kristo, kiu superas scion, por ke vi pleniĝu eĉ ĝis la pleneco de Dio.","kaj scii la amon de Kristo, kiu superas scion, por ke vi pleniĝu eĉ ĝis la pleneco de Dio."],[3,20,"Nun al Tiu, kiu povas tre abunde fari, super ĉio, kion ni povas peti aŭ pensi, laŭ la potenco, kiu energias en ni,","Nun al Tiu, kiu povas tre abunde fari, super ĉio, kion ni povas peti aŭ pensi, laŭ la potenco, kiu energias en ni,"],[3,21,"estu gloro en la eklezio kaj en Kristo Jesuo ĝis ĉiuj generacioj por ĉiam kaj eterne. Amen.","estu gloro en la eklezio kaj en Kristo Jesuo ĝis ĉiuj generacioj por ĉiam kaj eterne. Amen."],[4,1,"Mi do, malliberulo pro la Sinjoro, petegas vin, ke vi iradu inde je la voko, en kiu vi estas vokitaj,","Mi do, malliberulo pro la Sinjoro, petegas vin, ke vi iradu inde je la voko, en kiu vi estas vokitaj,"],[4,2,"kun ĉia humileco kaj mildeco, kun toleremeco, paciencante unu al alia en amo,","kun ĉia humileco kaj mildeco, kun toleremeco, paciencante unu al alia en amo,"],[4,3,"penante konservi la unuecon de la Spirito en la ligilo de paco.","penante konservi la unuecon de la Spirito en la ligilo de paco."],[4,4,"Estas unu korpo, kaj unu Spirito, kiel ankaŭ vi estas vokitaj en unu espero de via voko;","Estas unu korpo, kaj unu Spirito, kiel ankaŭ vi estas vokitaj en unu espero de via voko;"],[4,5,"unu Sinjoro, unu fido, unu bapto,","unu Sinjoro, unu fido, unu bapto,"],[4,6,"unu Dio kaj Patro de ĉiuj, kiu estas super ĉiuj, kaj tra ĉiuj, kaj en ĉiuj.","unu Dio kaj Patro de ĉiuj, kiu estas super ĉiuj, kaj tra ĉiuj, kaj en ĉiuj."],[4,7,"Sed al ĉiu el ni la graco estas donita, laŭ la mezuro de la dono de Kristo.","Sed al ĉiu el ni la graco estas donita, laŭ la mezuro de la dono de Kristo."],[4,8,"Tial li diras: Kiam li supreniris alten, li alkondukis kaptitojn, Kaj donis donacojn al homoj.","Tial li diras: Kiam li supreniris alten, li alkondukis kaptitojn, Kaj donis donacojn al homoj."],[4,9,"(Ĉi tio do: Li supreniris — kio ĝi estas krom tio, ke li ankaŭ antaŭe malsupreniris ĝis la profundaĵoj de la tero?","(Ĉi tio do: Li supreniris — kio ĝi estas krom tio, ke li ankaŭ antaŭe malsupreniris ĝis la profundaĵoj de la tero?"],[4,10,"La malsuprenirinto — tiu sama estis la suprenirinto alte super ĉiuj ĉieloj, por plenigi ĉion.)","La malsuprenirinto — tiu sama estis la suprenirinto alte super ĉiuj ĉieloj, por plenigi ĉion.)"],[4,11,"Kaj unujn li donis por esti apostoloj; aliajn, profetoj; aliajn, evangeliistoj; kaj aliajn, paŝtistoj kaj instruistoj;","Kaj unujn li donis por esti apostoloj; aliajn, profetoj; aliajn, evangeliistoj; kaj aliajn, paŝtistoj kaj instruistoj;"],[4,12,"por perfektigo de la sanktuloj, por la laboro de pastrado, por la konstruo de la korpo de Kristo,","por perfektigo de la sanktuloj, por la laboro de pastrado, por la konstruo de la korpo de Kristo,"],[4,13,"ĝis ni ĉiuj atingos la unuecon de la fido kaj de la scio de la Filo de Dio, ĝis la homo perfekta, ĝis la mezuro de la matureco de la pleneco de Kristo;","ĝis ni ĉiuj atingos la unuecon de la fido kaj de la scio de la Filo de Dio, ĝis la homo perfekta, ĝis la mezuro de la matureco de la pleneco de Kristo;"],[4,14,"por ke ni jam ne estu infanoj, onde ĵetataj kaj ĉirkaŭpelataj de ĉiu vento de doktrino, per ĵonglado de homoj, per ruzo laŭ artifiko de trompo;","por ke ni jam ne estu infanoj, onde ĵetataj kaj ĉirkaŭpelataj de ĉiu vento de doktrino, per ĵonglado de homoj, per ruzo laŭ artifiko de trompo;"],[4,15,"sed parolante la veron en amo, ni ĉiel kreskadu en tiun, kiu estas la kapo, Kristo,","sed parolante la veron en amo, ni ĉiel kreskadu en tiun, kiu estas la kapo, Kristo,"],[4,16,"el kiu la tuta korpo, kunigita kaj kunfortikigita tra ĉiu artiko de la livera sistemo, per energio, laŭ la mezuro de ĉiu parto, faras kreskadon de la korpo, por la sinedifado en amo.","el kiu la tuta korpo, kunigita kaj kunfortikigita tra ĉiu artiko de la livera sistemo, per energio, laŭ la mezuro de ĉiu parto, faras kreskadon de la korpo, por la sinedifado en amo."],[4,17,"La jenon do mi diras, kaj protestas en la Sinjoro, ke vi ne plu iru tiel, kiel iras ankaŭ la nacianoj en la vanteco de siaj mensoj,","La jenon do mi diras, kaj protestas en la Sinjoro, ke vi ne plu iru tiel, kiel iras ankaŭ la nacianoj en la vanteco de siaj mensoj,"],[4,18,"mallumigitaj en intelekto, fremdigitaj for de la vivo de Dio, pro la nescio, kiu estas en ili, pro la malmoleco de ilia koro;","mallumigitaj en intelekto, fremdigitaj for de la vivo de Dio, pro la nescio, kiu estas en ili, pro la malmoleco de ilia koro;"],[4,19,"kiuj, sensentiĝinte, fordonis sin al malĉasteco por la praktikado de ĉia malpureco kun avideco.","kiuj, sensentiĝinte, fordonis sin al malĉasteco por la praktikado de ĉia malpureco kun avideco."],[4,20,"Sed vi ne tiel lernis Kriston;","Sed vi ne tiel lernis Kriston;"],[4,21,"se almenaŭ vi lin aŭdis, kaj en li estis instruitaj, kiel en Jesuo estas vero;","se almenaŭ vi lin aŭdis, kaj en li estis instruitaj, kiel en Jesuo estas vero;"],[4,22,"por ke vi formetu, rilate al antaŭa konduto, la malnovan homon, pereeman laŭ trompaj deziroj,","por ke vi formetu, rilate al antaŭa konduto, la malnovan homon, pereeman laŭ trompaj deziroj,"],[4,23,"kaj renoviĝu rilate al la spirito de via menso,","kaj renoviĝu rilate al la spirito de via menso,"],[4,24,"kaj surmetu la novan homon, kreitan laŭ Dio en justeco kaj vera sankteco.","kaj surmetu la novan homon, kreitan laŭ Dio en justeco kaj vera sankteco."],[4,25,"Pro tio, formetante malveron, ĉiu parolu veron kun sia proksimulo, ĉar ni estas membroj unu de alia.","Pro tio, formetante malveron, ĉiu parolu veron kun sia proksimulo, ĉar ni estas membroj unu de alia."],[4,26,"Koleru kaj ne peku, la suno ne subiru sur via kolero;","Koleru kaj ne peku, la suno ne subiru sur via kolero;"],[4,27,"ankaŭ ne donu lokon al la diablo.","ankaŭ ne donu lokon al la diablo."],[4,28,"Ŝtelinto ne plu ŝtelu, sed prefere li laboru, farante bonon per siaj manoj, por ke li havu ion por doni al bezonanto.","Ŝtelinto ne plu ŝtelu, sed prefere li laboru, farante bonon per siaj manoj, por ke li havu ion por doni al bezonanto."],[4,29,"El via buŝo eliru neniu putra vorto, sed nur tio, kio estas bona, por konvena edifado, por ke ĝi donu gracon al la aŭdantoj.","El via buŝo eliru neniu putra vorto, sed nur tio, kio estas bona, por konvena edifado, por ke ĝi donu gracon al la aŭdantoj."],[4,30,"Kaj ne ĉagrenu la Sanktan Spiriton de Dio, en kiu vi estis sigelitaj al la tago de elaĉeto.","Kaj ne ĉagrenu la Sanktan Spiriton de Dio, en kiu vi estis sigelitaj al la tago de elaĉeto."],[4,31,"Ĉia akreco kaj indigno kaj kolero kaj voĉbruado kaj kalumnio estu formetitaj el inter vi, kune kun ĉia malico;","Ĉia akreco kaj indigno kaj kolero kaj voĉbruado kaj kalumnio estu formetitaj el inter vi, kune kun ĉia malico;"],[4,32,"kaj estu bonfaraj unu al alia, bonkoraj, pardonantaj unu al alia, kiel ankaŭ Dio en Kristo pardonis al vi.","kaj estu bonfaraj unu al alia, bonkoraj, pardonantaj unu al alia, kiel ankaŭ Dio en Kristo pardonis al vi."],[5,1,"Estu do imitantoj de Dio, kiel infanoj amataj;","Estu do imitantoj de Dio, kiel infanoj amataj;"],[5,2,"kaj iradu en amo, kiel Kristo nin amis kaj sin donis pro ni, donaĵon kaj oferaĵon al Dio por agrabla odoraĵo.","kaj iradu en amo, kiel Kristo nin amis kaj sin donis pro ni, donaĵon kaj oferaĵon al Dio por agrabla odoraĵo."],[5,3,"Sed malĉasteco kaj ĉia malpureco kaj avideco ne eĉ estu nomataj inter vi, kiel decas por sanktuloj;","Sed malĉasteco kaj ĉia malpureco kaj avideco ne eĉ estu nomataj inter vi, kiel decas por sanktuloj;"],[5,4,"nek ia hontindaĵo, nek sensenca parolado, nek tro libera babilado, kiuj ne konvenas; sed prefere dankesprimo.","nek ia hontindaĵo, nek sensenca parolado, nek tro libera babilado, kiuj ne konvenas; sed prefere dankesprimo."],[5,5,"Ĉar vi ja scias, ke ĉiu malĉastulo kaj malpurulo kaj avidulo, kiu estas idolano, havas nenian heredon en la regno de Kristo kaj Dio.","Ĉar vi ja scias, ke ĉiu malĉastulo kaj malpurulo kaj avidulo, kiu estas idolano, havas nenian heredon en la regno de Kristo kaj Dio."],[5,6,"Neniu vin trompu per vantaj vortoj; ĉar pro tiuj aferoj venas sur la infanojn de malobeo la kolero de Dio.","Neniu vin trompu per vantaj vortoj; ĉar pro tiuj aferoj venas sur la infanojn de malobeo la kolero de Dio."],[5,7,"Ne estu do partoprenantoj kun ili;","Ne estu do partoprenantoj kun ili;"],[5,8,"ĉar iam vi estis mallumo, sed jam vi estas lumo en la Sinjoro; iru kiel infanoj de lumo","ĉar iam vi estis mallumo, sed jam vi estas lumo en la Sinjoro; iru kiel infanoj de lumo"],[5,9,"(ĉar la frukto de la lumo estas en ĉia boneco kaj justeco kaj vero),","(ĉar la frukto de la lumo estas en ĉia boneco kaj justeco kaj vero),"],[5,10,"provante, kio bone plaĉas al la Sinjoro;","provante, kio bone plaĉas al la Sinjoro;"],[5,11,"kaj ne partoprenu kun la senfruktaj faroj de mallumo, sed prefere refutu ilin;","kaj ne partoprenu kun la senfruktaj faroj de mallumo, sed prefere refutu ilin;"],[5,12,"ĉar estas hontinde eĉ paroli pri tio, kion ili faras sekrete.","ĉar estas hontinde eĉ paroli pri tio, kion ili faras sekrete."],[5,13,"Sed ĉio, kio estas refutata, estas elmontrata per la lumo, ĉar ĉio elmontrata estas lumo.","Sed ĉio, kio estas refutata, estas elmontrata per la lumo, ĉar ĉio elmontrata estas lumo."],[5,14,"Tial estas dirite: Vekiĝu, dormanto, kaj releviĝu el la mortintoj, kaj Kristo al vi lumos.","Tial estas dirite: Vekiĝu, dormanto, kaj releviĝu el la mortintoj, kaj Kristo al vi lumos."],[5,15,"Zorgu do, ke vi atente iradu, ne kiel malsaĝaj, sed kiel saĝaj;","Zorgu do, ke vi atente iradu, ne kiel malsaĝaj, sed kiel saĝaj;"],[5,16,"elaĉetante la tempon, ĉar malbonaj estas la tagoj.","elaĉetante la tempon, ĉar malbonaj estas la tagoj."],[5,17,"Ne estu do senprudentaj, sed komprenu, kio estas la volo de la Sinjoro.","Ne estu do senprudentaj, sed komprenu, kio estas la volo de la Sinjoro."],[5,18,"Kaj ne ebriiĝu per vino, en kio estas diboĉo, sed pleniĝu per la Spirito;","Kaj ne ebriiĝu per vino, en kio estas diboĉo, sed pleniĝu per la Spirito;"],[5,19,"parolante unu al alia per psalmoj kaj himnoj kaj kantoj spiritaj, kantante kaj psalmante en viaj koroj al la Sinjoro,","parolante unu al alia per psalmoj kaj himnoj kaj kantoj spiritaj, kantante kaj psalmante en viaj koroj al la Sinjoro,"],[5,20,"dankante Dion, la Patron, ĉiam pro ĉio en la nomo de nia Sinjoro Jesuo Kristo;","dankante Dion, la Patron, ĉiam pro ĉio en la nomo de nia Sinjoro Jesuo Kristo;"],[5,21,"submetiĝante unu al alia en la timo al Kristo.","submetiĝante unu al alia en la timo al Kristo."],[5,22,"Edzinoj, submetiĝu al viaj edzoj tiel same, kiel al la Sinjoro.","Edzinoj, submetiĝu al viaj edzoj tiel same, kiel al la Sinjoro."],[5,23,"Ĉar edzo estas kapo de edzino, kiel ankaŭ Kristo estas kapo de la eklezio; kaj li estas la savanto de la korpo.","Ĉar edzo estas kapo de edzino, kiel ankaŭ Kristo estas kapo de la eklezio; kaj li estas la savanto de la korpo."],[5,24,"Sed kiel la eklezio sin submetas al Kristo, tiel ankaŭ edzinoj al edzoj en ĉio.","Sed kiel la eklezio sin submetas al Kristo, tiel ankaŭ edzinoj al edzoj en ĉio."],[5,25,"Edzoj, amu viajn edzinojn, kiel Kristo amis la eklezion kaj pro ĝi sin donis,","Edzoj, amu viajn edzinojn, kiel Kristo amis la eklezion kaj pro ĝi sin donis,"],[5,26,"por ke li sanktigu ĝin per akvolavo, kun la vorto,","por ke li sanktigu ĝin per akvolavo, kun la vorto,"],[5,27,"por ke li starigu ĝin antaŭ si glora eklezio, ne havanta makulon, nek malglataĵon, nek ion tian, sed por ke ĝi estu sankta kaj sendifekta.","por ke li starigu ĝin antaŭ si glora eklezio, ne havanta makulon, nek malglataĵon, nek ion tian, sed por ke ĝi estu sankta kaj sendifekta."],[5,28,"Tiel same devas edzoj ami siajn edzinojn kiel siajn proprajn korpojn. Kiu amas sian edzinon, tiu amas sin mem;","Tiel same devas edzoj ami siajn edzinojn kiel siajn proprajn korpojn. Kiu amas sian edzinon, tiu amas sin mem;"],[5,29,"ĉar oni neniam malamas sian propran karnon, sed nutras kaj prizorgas ĝin, kiel ankaŭ la Sinjoro la eklezion;","ĉar oni neniam malamas sian propran karnon, sed nutras kaj prizorgas ĝin, kiel ankaŭ la Sinjoro la eklezion;"],[5,30,"ĉar ni estas membroj de lia korpo.","ĉar ni estas membroj de lia korpo."],[5,31,"Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino, kaj ili du estos unu karno.","Tial viro forlasos sian patron kaj sian patrinon, kaj aliĝos al sia edzino, kaj ili du estos unu karno."],[5,32,"Ĉi tiu mistero estas granda, sed mi parolas pri Kristo kaj la eklezio.","Ĉi tiu mistero estas granda, sed mi parolas pri Kristo kaj la eklezio."],[5,33,"Tamen ankaŭ ĉiu el vi individue amu sian edzinon, kiel sin mem; kaj la edzino timu sian edzon.","Tamen ankaŭ ĉiu el vi individue amu sian edzinon, kiel sin mem; kaj la edzino timu sian edzon."],[6,1,"Infanoj, obeu al viaj gepatroj en la Sinjoro, ĉar tio decas.","Infanoj, obeu al viaj gepatroj en la Sinjoro, ĉar tio decas."],[6,2,"Respektu vian patron kaj vian patrinon (ĝi estas la unua ordono kun promeso),","Respektu vian patron kaj vian patrinon (ĝi estas la unua ordono kun promeso),"],[6,3,"por ke estu al vi bone kaj por ke longe daŭru via vivo sur la tero.","por ke estu al vi bone kaj por ke longe daŭru via vivo sur la tero."],[6,4,"Kaj patroj, ne kolerigu viajn infanojn; sed nutradu ilin en la disciplino kaj admono de la Sinjoro.","Kaj patroj, ne kolerigu viajn infanojn; sed nutradu ilin en la disciplino kaj admono de la Sinjoro."],[6,5,"Sklavoj, obeu al tiuj, kiuj laŭ la karno estas viaj sinjoroj, kun timo kaj tremo, en simpleco de via koro, kiel al Kristo;","Sklavoj, obeu al tiuj, kiuj laŭ la karno estas viaj sinjoroj, kun timo kaj tremo, en simpleco de via koro, kiel al Kristo;"],[6,6,"ne laŭ okulservo, kiel homplaĉantoj, sed kiel sklavoj de Kristo, plenumante el la koro la volon de Dio;","ne laŭ okulservo, kiel homplaĉantoj, sed kiel sklavoj de Kristo, plenumante el la koro la volon de Dio;"],[6,7,"kun bonvoleco servante, kiel al la Sinjoro, kaj ne al homoj;","kun bonvoleco servante, kiel al la Sinjoro, kaj ne al homoj;"],[6,8,"sciante, ke, kian ajn bonon faras ĉiu, ĉu sklavo aŭ liberulo, tion saman li ricevos de la Sinjoro.","sciante, ke, kian ajn bonon faras ĉiu, ĉu sklavo aŭ liberulo, tion saman li ricevos de la Sinjoro."],[6,9,"Kaj sinjoroj, agu tiel same al ili, forlasante minacon; sciante, ke via kaj ilia Sinjoro estas en la ĉielo, kaj ne ekzistas ĉe li personfavorado.","Kaj sinjoroj, agu tiel same al ili, forlasante minacon; sciante, ke via kaj ilia Sinjoro estas en la ĉielo, kaj ne ekzistas ĉe li personfavorado."],[6,10,"Cetere, fortiĝu en la Sinjoro kaj en la forteco de lia potenco.","Cetere, fortiĝu en la Sinjoro kaj en la forteco de lia potenco."],[6,11,"Surmetu la tutan armilaron de Dio, por ke vi povu kontraŭstari al la artifikoj de la diablo.","Surmetu la tutan armilaron de Dio, por ke vi povu kontraŭstari al la artifikoj de la diablo."],[6,12,"Ĉar nia luktado estas ne kontraŭ sango kaj karno, sed kontraŭ regantoj, kontraŭ aŭtoritatoj, kontraŭ mondpotenculoj de la nuna mallumo, kontraŭ la spiritaroj de malbono en la ĉielejoj.","Ĉar nia luktado estas ne kontraŭ sango kaj karno, sed kontraŭ regantoj, kontraŭ aŭtoritatoj, kontraŭ mondpotenculoj de la nuna mallumo, kontraŭ la spiritaroj de malbono en la ĉielejoj."],[6,13,"Tial prenu al vi la tutan armilaron de Dio, por ke vi povu rezisti en la malbona tago, kaj, farinte ĉion, stari.","Tial prenu al vi la tutan armilaron de Dio, por ke vi povu rezisti en la malbona tago, kaj, farinte ĉion, stari."],[6,14,"Staru do, ĉirkaŭzoninte la lumbojn per vero, kaj surmetinte la kirason de justeco,","Staru do, ĉirkaŭzoninte la lumbojn per vero, kaj surmetinte la kirason de justeco,"],[6,15,"kaj enŝuiginte la piedojn per la pretiĝo de la evangelio de paco;","kaj enŝuiginte la piedojn per la pretiĝo de la evangelio de paco;"],[6,16,"super ĉio tenante la ŝildon de fido, per kiu vi povos estingi ĉiujn fajrajn sagojn de la malbonulo.","super ĉio tenante la ŝildon de fido, per kiu vi povos estingi ĉiujn fajrajn sagojn de la malbonulo."],[6,17,"Kaj ricevu la kaskon de savo, kaj la glavon de la Spirito, kiu estas la vorto de Dio;","Kaj ricevu la kaskon de savo, kaj la glavon de la Spirito, kiu estas la vorto de Dio;"],[6,18,"per ĉia preĝado kaj petegado en ĉiu tempo preĝante en la Spirito, kaj viglante por tio en ĉia persisteco kaj petego por ĉiuj sanktuloj,","per ĉia preĝado kaj petegado en ĉiu tempo preĝante en la Spirito, kaj viglante por tio en ĉia persisteco kaj petego por ĉiuj sanktuloj,"],[6,19,"kaj por mi, ke al mi estu donita parolpovo kun malfermo de mia buŝo, por ke mi sciigu kuraĝe la misteron de la evangelio,","kaj por mi, ke al mi estu donita parolpovo kun malfermo de mia buŝo, por ke mi sciigu kuraĝe la misteron de la evangelio,"],[6,20,"pro kiu mi estas ambasadoro en kateno, por ke mi parolu kuraĝe en ĝi, kiel mi devus paroli.","pro kiu mi estas ambasadoro en kateno, por ke mi parolu kuraĝe en ĝi, kiel mi devus paroli."],[6,21,"Plue, por ke vi sciiĝu pri miaj aferoj, kiel mi statas, raportos ĉion al vi Tiĥiko, la amata frato kaj fidela diakono en la Sinjoro,","Plue, por ke vi sciiĝu pri miaj aferoj, kiel mi statas, raportos ĉion al vi Tiĥiko, la amata frato kaj fidela diakono en la Sinjoro,"],[6,22,"kiun mi sendis al vi ĝuste por tio, ke vi sciiĝu pri nia stato kaj por ke li konsolu viajn korojn.","kiun mi sendis al vi ĝuste por tio, ke vi sciiĝu pri nia stato kaj por ke li konsolu viajn korojn."],[6,23,"Paco estu al la fratoj, kaj amo kun fido de Dio, la Patro, kaj de la Sinjoro Jesuo Kristo.","Paco estu al la fratoj, kaj amo kun fido de Dio, la Patro, kaj de la Sinjoro Jesuo Kristo."],[6,24,"Graco estu kun ĉiuj, kiuj sendekliniĝe amas nian Sinjoron Jesuo Kristo.","Graco estu kun ĉiuj, kiuj sendekliniĝe amas nian Sinjoron Jesuo Kristo."]]}};